      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "The tip of his tongue entwined around me and then let go, only to then barge in even deeper. It swept and scraped over every crevice of my mouth, sending goosebumps rising down my spine.",
