    [77] = {
      beijing = 4790,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "A mixture of clothes rustling and hearts beating seemed to roar in my ears, and the heat that I'd found so painful gradually didn't seem so unbearable anymore.",
