    [78] = {
      beijing = 4790,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "It seemed at this moment that his vigorous Yang energy and my smoldering Yin energy finally found a starting point of agreement and began tentatively intermingling.",
