    [79] = {
      beijing = 4790,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "My vision kept swaying, and everything looked bizarre and kaleidoscopic as the pain of my past gradually receded away like a tide.",
